import {people,recipes,seed,split,balance,normalize,missingIngredients,addIngredients,money} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',plans:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Zm3 10h2m4 0h2m-8 4h2',shopping:'m3 4 2 2 2 11h12l2-8H6m3 12h.01M18 21h.01',spending:'M3 6h18v14H3Zm0 0V4h15v2m-2 6h5v4h-5Z',household:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-7a4 4 0 0 1 0 7',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',leaf:'M20 3C8 2 2 8 5 15c4 8 16 2 15-12ZM4 21 15 9',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',camera:'M3 6h5l2-3h4l2 3h5v14H3Zm13 7a4 4 0 1 0-8 0 4 4 0 0 0 8 0Z',clock:'M12 8v5l3 2m7-3a10 10 0 1 0-20 0 10 10 0 0 0 20 0Z',info:'M12 11v6m0-10h.01m10 5a10 10 0 1 0-20 0 10 10 0 0 0 20 0Z',edit:'m16 3 5 5-12 12-6 1 1-6Zm-9 12 5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',map:'m3 5 6-3 6 3 6-3v17l-6 3-6-3-6 3Zm6-3v17m6-14v17'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`;
let state;try{const s=JSON.parse(localStorage.getItem('common-demo-v1'));state=s?.version===1&&Array.isArray(s.items)&&Array.isArray(s.profiles)&&Array.isArray(s.expenses)&&Array.isArray(s.payments)&&Array.isArray(s.plans)&&s.profiles.length===4?s:seed();balance(state,state.actor);}catch{state=seed();}
let filter='All',query='',activePlan=state.plans[0]?.id||'movie',toastTimer,photoUrl,pendingArrival=[];
const person=id=>state.profiles.find(p=>p.id===id)||people[0];
const avatar=id=>`<span class="avatar ${person(id).color}" aria-label="${esc(person(id).name)}">${esc(person(id).name[0])}</span>`;
const names=ids=>ids.map(id=>person(id).name).join(', ');
const page=()=>['tonight','plans','shopping','spending','household'].includes(location.hash.slice(1))?location.hash.slice(1):'tonight';
const plan=()=>state.plans.find(p=>p.id===activePlan)||state.plans[0];
const votesForPlan=()=>plan().votes||(plan().votes=structuredClone(state.votes));
function save(){try{localStorage.setItem('common-demo-v1',JSON.stringify(state));}catch{toast('Storage is unavailable. Changes will last until you reload.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function go(p){if(page()===p)render();else location.hash=p;}
function title(heading,sub,action='',label=''){return `<div class="page-title"><div><h1>${esc(heading)}</h1><p class="sub">${esc(sub)}</p></div>${action?`<button class="btn primary" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`;}
function membersField(ids=people.map(p=>p.id),label='Who is sharing this?'){return `<fieldset><legend>${label}</legend><div class="member-options">${state.profiles.map(p=>`<label class="member-option"><input type="checkbox" name="members" value="${p.id}" ${ids.includes(p.id)?'checked':''}>${p.name}</label>`).join('')}</div></fieldset>`;}
const options=(ids=people.map(p=>p.id),selected=state.actor)=>ids.map(id=>`<option value="${id}" ${id===selected?'selected':''}>${person(id).name}</option>`).join('');
function stack(ids=people.map(p=>p.id)){return `<div class="avatar-stack">${ids.map(avatar).join('')}<span>${ids.length} joining</span></div>`;}
function recipeCard(r){const picked=votesForPlan()[r.id]?.includes(state.actor),n=votesForPlan()[r.id]?.length||0;return `<article class="recipe"><div class="recipe-img"><button class="image-link" data-action="recipe" data-id="${r.id}" aria-label="View ${r.name}"><img src="assets/${r.image}.jpg" alt="${r.id==='tacos'?'Vegetable tacos on a table':r.id==='salad'?'A colorful bowl of greens and toppings':'A creamy pasta bowl'}" loading="lazy"></button><button class="save ${state.saved.includes(r.id)?'active':''}" data-action="favorite" data-id="${r.id}" aria-label="${state.saved.includes(r.id)?'Unsave':'Save'} ${r.name}" aria-pressed="${state.saved.includes(r.id)}">${icon('heart')}</button></div><h3><button class="text-button" data-action="recipe" data-id="${r.id}">${r.name}</button></h3><p class="recipe-meta">${r.minutes} min · 4 servings · ~${money(r.price*100)}/person</p><div class="recipe-vote"><span>${state.voting?`${n} ${n===1?'pick':'picks'}`:r.tag}</span><button class="pick ${picked?'selected':''}" data-action="${state.voting?'vote':'recipe'}" data-id="${r.id}" ${state.voting?`aria-pressed="${picked}"`:''}>${state.voting?(picked?'Picked':'I’m in'):'View recipe'}</button></div></article>`;}
function journey(){const p=plan();return `<div class="plan-journey" aria-label="Your plan’s progress"><div class="journey-step done">${icon('household')}Make a plan</div><div class="journey-step ${p?.menu?'done':''}">${icon('leaf')}Choose food</div><div class="journey-step ${p?.menu?'done':''}">${icon('shopping')}Shop together</div><div class="journey-step">${icon('spending')}Split fairly</div></div>`;}
function tonight(){const p=plan(),owed=balance(state,state.actor).filter(([,c])=>c>0),total=owed.reduce((s,[,c])=>s+c,0);return `${title('Good food. Your people.','A little less “who’s getting what?” A little more together.','new-plan','Make a plan')}<div class="workspace"><section><div class="feature"><img src="assets/table.jpg" alt="A shared meal on a sunlit wooden dining table" fetchpriority="high"><div class="feature-content"><div class="feature-info">${icon('clock')} ${esc(formatDate(p.date))} · ${esc(formatTime(p.time))}</div><h2>${esc(p.name)}</h2><div class="feature-bottom">${stack(p.members)}<button class="btn light" data-action="open-plan" data-id="${p.id}">Plan the menu ${icon('arrow')}</button></div></div></div>${journey()}<div class="section-head"><h2>What sounds good?</h2><span class="small">For your kind of evening</span></div><div class="theme-row">${['Movie night','Taco Tuesday','Quick dinner','Use what we have'].map(t=>`<button class="chip ${state.theme===t?'selected':''}" data-action="theme" data-id="${t}" aria-pressed="${state.theme===t}">${t}</button>`).join('')}</div><div class="recipe-grid">${orderedRecipes().map(recipeCard).join('')}</div><p class="photo-disclaimer">Sample suggestions & estimates · Photography is illustrative</p></section><aside class="side"><section class="inspo">${icon('spark')}<h2>From saved<br>to served.</h2><p>That dish in your camera roll? Give it a place at the table.</p><button class="btn full" data-action="inspiration">${icon('camera')} Bring a food photo</button></section><section class="side-section"><div class="side-heading"><h3>On the way home</h3><a href="#shopping" aria-label="View shopping list">${icon('arrow')}</a></div>${state.items.filter(i=>!i.bought).slice(0,2).map(i=>`<div class="mini-row">${i.owner?avatar(i.owner):`<span class="avatar">${icon('shopping')}</span>`}<div><strong>${esc(i.name)}</strong><p>${i.owner?esc(person(i.owner).name):'Up for grabs'} · ${esc(i.store)}</p></div></div>`).join('')||'<p class="small muted">Your list is all caught up.</p>'}<button class="btn ghost slim" data-action="assign">Find a good shopping fit ${icon('arrow')}</button></section><section class="side-section"><h3>A fair share</h3><div class="balance-big money">${money(total)}</div><p class="small muted">${total?`You owe ${owed.map(([id])=>person(id).name).join(' and ')} for shared purchases.`:'You’re all caught up on what you owe.'}</p><a class="btn ghost slim" href="#spending">See the breakdown ${icon('arrow')}</a></section><p class="aside-note">${icon('info')} Interactive concept. Sample household, local data, simulated AI.</p></aside></div><footer class="bottom-note"><span>Made for the everyday things you share.</span><span>Maple House · 4 people · Your changes stay in this browser</span></footer>`;}
function orderedRecipes(){if(state.theme==='Use what we have')return [recipes[1],recipes[0],recipes[2]];if(state.theme==='Quick dinner')return [recipes[1],recipes[2],recipes[0]];return recipes;}
function formatDate(d){return new Date(`${d}T12:00:00`).toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'});}
function formatTime(t){const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'pm':'am'}`;}
function plans(){const p=plan();return `${title('Good things on the calendar.','Dinner for four. A party for friends. There’s room for both.','new-plan','Make a plan')}<div class="split-layout"><section><div class="week" aria-label="Sample week of October 12">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>`<div class="day ${i===5?'today':''}">${d}<b>${12+i}</b></div>`).join('')}</div>${state.plans.map(p=>`<div class="event-row"><div class="date-tile">${new Date(`${p.date}T12:00`).toLocaleDateString('en-US',{month:'short'})}<b>${Number(p.date.slice(-2))}</b></div><div class="event-copy"><h3>${esc(p.name)}</h3><p>${esc(formatTime(p.time))} · ${p.members.length} people · ${esc(p.theme)}</p><p>${p.menu?`Menu: ${recipes.find(r=>r.id===p.menu)?.name}`:'Menu open for ideas'}</p></div><button class="btn slim" data-action="open-plan" data-id="${p.id}">Choose food ${icon('arrow')}</button></div>`).join('')}<div class="section-head"><h2>A menu everyone can get behind.</h2></div><p class="small muted">Choosing for <strong>${esc(p.name)}</strong> · ${esc(names(p.members))}</p><div class="voting-info"><p>${state.voting?'Everyone gets a say. Switch the person in the top bar to try group voting.':'Votes are off. Open a recipe and choose the menu directly.'}</p><a href="#household" class="btn ghost slim">Voting settings</a></div><div class="recipe-grid">${recipes.map(recipeCard).join('')}</div><p class="photo-disclaimer">Votes show interest. Confirming a meal keeps its cost participants explicit.</p></section><aside><section class="panel"><h2>Give the evening a little character.</h2><p class="small muted">Start with an occasion, then make the menu your own.</p><div class="theme-row">${['Taco Tuesday','Movie night','Potluck party','Use what we have'].map(t=>`<button class="chip" data-action="new-themed-plan" data-id="${t}">${t}</button>`).join('')}</div><p class="small muted">A party can have its own name and participants. This demo uses four sample household members.</p></section><section class="note settings-note"><strong>Room for different tastes</strong><p>One shared base, toppings on the side. Preferences help suggest a starting point; people make the final call.</p></section></aside></div>`;}
function shopping(){const unlogged=state.items.filter(i=>i.bought&&!i.logged),shown=state.items.filter(i=>(filter==='All'||filter==='Unclaimed'&&!i.owner&&!i.bought||filter==='Mine'&&i.owner===state.actor&&!i.bought||filter==='Bought'&&i.bought)&&normalize(i.name).includes(normalize(query)));return `${title('A list with a little less guesswork.','What we need, what we have, and who’s picking it up.','add-item','Add an item')}<div class="toolbar"><div class="tabs">${['All','Unclaimed','Mine','Bought'].map(f=>`<button class="chip ${filter===f?'selected':''}" data-action="filter" data-id="${f}" aria-pressed="${filter===f}">${f}${f==='All'?` (${state.items.length})`:''}</button>`).join('')}</div><input class="search" type="search" id="search" aria-label="Search shopping list" placeholder="Find something on the list" value="${esc(query)}"></div><div class="shopping-list">${shown.length?shown.map(i=>`<div class="shopping-row ${pendingArrival.includes(i.id)?'just-added':''} ${i.bought?'bought':''}"><input class="check" type="checkbox" data-change="bought" data-id="${i.id}" ${i.bought?'checked':''} ${i.logged?'disabled':''} aria-label="Mark ${esc(i.name)} bought"><div><h3>${esc(i.name)}</h3><p>${esc(i.quantity)} · ${esc(i.store)} · ${i.members.length===1?`${esc(person(i.members[0]).name)} only`:i.members.length===4?'Shared by all':`Shared by ${esc(names(i.members))}`}${i.logged?' · Cost recorded':''}</p></div><div class="owner">${i.owner?`${avatar(i.owner)} ${esc(person(i.owner).name)}`:'Unclaimed'}</div>${i.bought?`<button class="btn slim" data-action="edit-item" data-id="${i.id}" ${i.logged?'disabled':''}>${i.logged?'Recorded':'Details'}</button>`:`<button class="btn slim" data-action="${i.owner===state.actor?'release':'claim'}" data-id="${i.id}">${i.owner===state.actor?'Release':i.owner?'Reassign to me':'I’ll get it'}</button>`}<button class="icon-button" data-action="edit-item" data-id="${i.id}" aria-label="Edit ${esc(i.name)}" ${i.logged?'disabled':''}>${icon('edit')}</button></div>`).join(''):`<div class="empty"><h3>${query?'No items found.':'Nothing here just yet.'}</h3><p>${query?'Try another search or add what you need.':'Add an item or pick a meal to get started.'}</p></div>`}</div><div class="form-actions"><button class="btn" data-action="assign">${icon('map')} Suggest who shops</button><button class="btn primary" data-action="record-trip" ${unlogged.length?'':'disabled'}>Record costs${unlogged.length?` (${unlogged.length})`:''}</button></div><p class="small muted">Check off purchases first, then enter the actual receipt amounts. Checking an item alone creates no expense.</p><div class="section-head"><h2>Before we buy it again.</h2><span class="small">Our kitchen</span></div><div class="split-layout"><section>${state.pantry.map((p,i)=>`<div class="stock-row"><div><h3>${esc(p.name)} <span class="muted">· ${esc(p.quantity)}</span></h3><p>Last confirmed ${esc(p.confirmed)} · Update when you check</p></div><select aria-label="Stock status for ${esc(p.name)}" data-change="stock" data-id="${i}">${['Have','Use soon','Out','Unsure'].map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')}</section><aside class="note"><div><strong>Shared doesn’t mean everything.</strong><p>Jordan’s oat milk stays Jordan’s expense. Each item keeps its own participants when you record a shopping trip.</p></div></aside></div>`;}
function spending(){const balances=balance(state,state.actor);return `${title('Keep the good stuff shared.','A clear record of who paid, who joined, and what’s left to settle.','add-expense','Add an expense')}<div class="split-layout"><section><div class="list-header"><h2>Purchase history</h2><span class="small muted">Actual amounts · USD</span></div>${state.expenses.map(e=>`<div class="expense-row">${avatar(e.payer)}<div class="expense-copy"><h3>${esc(e.name)}</h3><p>${esc(person(e.payer).name)} paid · ${esc(e.date)}<br>${e.members.length===1?`${esc(person(e.members[0]).name)} only`:esc(names(e.members))} · ${e.members.length} ${e.members.length===1?'person':'people'}</p></div><div class="expense-amount money">${money(e.cents)}<p class="small muted">${money(split(e.cents,e.members)[state.actor]||0)} your share</p></div></div>`).join('')}<div class="note settings-note"><strong>Estimates never become debt.</strong><p>Recipe estimates are just for planning. Only recorded purchase amounts enter this ledger. Rounding is handled in cents, so every split adds up.</p></div>${state.payments.length?`<div class="section-head"><h2>Repayment notes</h2></div>${state.payments.map(p=>`<div class="expense-row"><div class="expense-copy"><h3>${esc(person(p.from).name)} → ${esc(person(p.to).name)} · ${money(p.cents)}</h3><p>${p.confirmed?'Receipt confirmed in this demo':'Reported sent · Awaiting recipient confirmation'} · ${esc(p.method)}</p></div>${!p.confirmed&&state.actor===p.to?`<button class="btn slim" data-action="confirm-payment" data-id="${p.id}">Confirm receipt</button>`:''}</div>`).join('')}`:''}</section><aside><section class="panel"><h2>${esc(person(state.actor).name)}’s balance</h2>${balances.length?balances.map(([id,c])=>`<div class="settlement">${avatar(id)}<div><p>${c>0?`You owe ${esc(person(id).name)}`:`${esc(person(id).name)} owes you`}</p><strong class="money">${money(Math.abs(c))}</strong></div>${c>0?`<button class="btn slim" data-action="repay" data-id="${id}">Settle</button>`:''}</div>`).join(''):'<p class="small muted">All settled. A good place to be.</p>'}<p class="small muted" style="margin-top:18px">Balances update after the recipient confirms a repayment.</p></section><div class="note settings-note"><strong>Payments are a handoff.</strong><p>This concept shows a Venmo / Zelle handoff. It doesn’t move money or connect to bank accounts.</p></div></aside></div>`;}
function household(){return `${title('The people around your table.','Preferences for better plans. Clear boundaries for shared purchases.')}<div class="split-layout"><section>${state.profiles.map(p=>`<article class="profile">${avatar(p.id)}<div><h3>${esc(p.name)}${p.id===state.actor?' <span class="muted small">(you in this demo)</span>':''}</h3><p>${esc(p.note)}</p><p class="small">${icon('map')} ${esc(p.store)} · ${esc(p.reason)}<br>${esc(p.membership)}</p></div><button class="btn slim" data-action="edit-profile" data-id="${p.id}">Edit</button></article>`).join('')}<div class="section-head"><h2>Make it work your way.</h2></div><label class="setting"><div><strong>Let the group vote</strong><p>People can pick meals they’d enjoy. Turn it off for a quicker, direct decision.</p></div><input class="switch" type="checkbox" data-change="voting" ${state.voting?'checked':''}></label><label class="setting"><div><strong>Auto-add unanimous matches</strong><p>When all four household members pick the same recipe, add only its missing ingredients for all four. You can still review the shopping list.</p></div><input class="switch" type="checkbox" data-change="matching" ${state.matching?'checked':''} ${!state.voting?'disabled':''}></label><div class="note"><strong>People stay in control.</strong><p>Preferences are editable. Store and membership details are self-reported; no subscriptions, live locations, or accounts are linked. Recipe suggestions need an ingredient and allergy check.</p></div></section><aside><section class="panel"><h2>Try being someone else.</h2><p class="small muted">Use the person menu at the top to vote, claim an errand, or confirm a repayment as another sample roommate.</p><div class="setting"><div><strong>Browser-local demo</strong><p>Changes are stored on this device. This isn’t a live group account.</p></div></div><button class="btn full" data-action="reset">Reset sample household</button></section></aside></div>`;}
function render(){const current=page();$('#app').innerHTML=`<div class="shell"><aside class="rail"><a class="brand" href="#tonight">common<span class="brand-dot">.</span></a><div class="house">${icon('home')} Maple House <span>${icon('down')}</span></div><nav class="nav" aria-label="Main navigation">${[['tonight','home','Tonight'],['plans','plans','Our plans'],['shopping','shopping','Shopping'],['spending','spending','Spending'],['household','household','Household']].map(([p,i,t])=>`<a href="#${p}" class="${p===current?'active':''}" ${p===current?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="rail-footer"><div class="mini-leaf">${icon('leaf')}</div><strong class="small">A little more together.</strong><p>A shared table.<br>A lighter everyday.</p></div></aside><div class="stage"><header class="topbar"><a class="mobile-brand" href="#tonight">common.</a><div class="topbar-left">Maple House <span class="muted">/</span> <span class="muted">${({tonight:'Tonight',plans:'Our plans',shopping:'Shopping',spending:'Spending',household:'Household'})[current]}</span></div><div class="topbar-right"><span class="demo-tag"><i class="demo-dot"></i> Sample household</span><label class="actor">${avatar(state.actor)}<select id="actor" aria-label="Try demo as">${options()}</select></label></div></header><main class="main" id="main" tabindex="-1">${({tonight,plans,shopping,spending,household})[current]()}</main></div></div>`;pendingArrival=[];}
function modal(heading,body){const d=$('#dialog');if(d.open)d.close();d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${heading}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;d.showModal();}
const close=()=>{$('#dialog').close();if(photoUrl){URL.revokeObjectURL(photoUrl);photoUrl=null;}};
function recipeDialog(id){const r=recipes.find(r=>r.id===id);modal(r.name,`<img class="dialog-photo" src="assets/${r.image}.jpg" alt="Illustrative meal photo"><div class="recipe-detail-meta"><span>${r.minutes} minutes</span><span>4 servings</span><span>~${money(r.price*100)}/person</span></div><p>${r.description}</p><div class="note"><strong>Why it could work for your household</strong><p>${r.why}</p></div><h3>Make it together</h3><ol class="steps">${r.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="photo-disclaimer">Curated sample recipe, not live AI output. Photo is illustrative. Check labels, allergies, and cooking suitability before preparing.</p><button class="btn primary full" data-action="review" data-id="${id}">Review ingredients ${icon('arrow')}</button>`);}
function reviewDialog(id){const r=recipes.find(r=>r.id===id),items=missingIngredients(state,r),n=items.filter(i=>!i.stock&&!i.listed).length;modal('A quick look before we shop.',`<p><strong>${r.name}</strong> · Recipe quantities serve four. Adjust quantities on the list if fewer people join.</p><div class="note">We checked your sample kitchen and shopping list. Only missing ingredients will be added; existing entries keep their current participants.</div>${items.map(i=>`<div class="ingredient"><div>${i.name}<small>${i.quantity}${i.listed?` · Currently for ${esc(names(i.listed.members))}`:''}</small></div><span class="status ${!i.stock&&!i.listed?'new':''}">${i.stock?'In the kitchen':i.listed?'Already listed':'Add to list'}</span></div>`).join('')}<form data-form="confirm-menu" data-id="${id}">${membersField(plan()?.members)}<p class="small muted">Votes don’t decide who pays. These participants will share the new ingredients.</p><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">Keep browsing</button><button class="btn primary">Confirm menu · ${n} new ${n===1?'item':'items'}</button></div></form>`);}
function newPlan(theme='Movie night'){modal('Something to look forward to.',`<p>Make an occasion, then find food that fits the people joining.</p><form data-form="new-plan"><label class="field">Plan name<input name="name" required maxlength="80" placeholder="Sunday dinner, game night, a birthday…"></label><div class="form-grid"><label class="field">Date<input name="date" type="date" required value="2026-10-18"></label><label class="field">Time<input name="time" type="time" required value="18:30"></label></div><label class="field">Kind of gathering<select name="theme">${['Movie night','Taco Tuesday','Quick dinner','Use what we have','Potluck party','Other'].map(t=>`<option ${theme===t?'selected':''}>${t}</option>`).join('')}</select></label>${membersField()}<p class="small muted">For this demo, guests are represented by the four sample members.</p><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary">Create plan</button></div></form>`);}
function itemDialog(id){const i=state.items.find(i=>i.id===id);modal(i?'Make the list clearer.':'What else do we need?',`<form data-form="item" data-id="${id||''}"><label class="field">Item name<input name="name" required maxlength="80" value="${esc(i?.name||'')}" placeholder="Snacks, dish soap, a speaker…"></label><div class="form-grid"><label class="field">Quantity<input name="quantity" required maxlength="40" value="${esc(i?.quantity||'')}" placeholder="2 bags"></label><label class="field">Store<input name="store" required maxlength="50" value="${esc(i?.store||'')}" placeholder="Choose any store"></label></div><label class="field">Who’s getting it?<select name="owner"><option value="">Up for grabs</option>${options(undefined,i?.owner||'')}</select></label>${membersField(i?.members)}<p class="error" role="alert"></p><div class="form-actions">${i?`<button type="button" class="btn" data-action="delete-item" data-id="${i.id}">Remove item</button>`:''}<button class="btn primary">${i?'Save changes':'Add to list'}</button></div></form>`);}
function assignDialog(){const available=state.items.filter(i=>!i.owner&&!i.bought);modal('Who’s already heading that way?',`<p>Simple suggestions from your household’s recorded stores. No location tracking or subscription access.</p>${available.length?`<form data-form="assign">${available.map(i=>{const suggestion=state.profiles.find(p=>normalize(p.store)===normalize(i.store));return `<div class="ingredient"><div><strong>${esc(i.name)}</strong><small>${esc(i.store)}${suggestion?` · ${esc(suggestion.reason)}`:' · Choose someone who’s free'}</small></div><label class="field" style="margin:0"><span class="small">Shopper</span><select name="owner-${i.id}"><option value="">Keep unclaimed</option>${options(undefined,suggestion?.id||'')}</select></label></div>`;}).join('')}<div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary">Save assignments</button></div></form>`:'<div class="note">Everything is claimed or bought. Open Shopping to change an assignment.</div><a class="btn primary full" href="#shopping" data-action="close">View shopping</a>'}`);}
function recordTrip(){const items=state.items.filter(i=>i.bought&&!i.logged);if(!items.length)return toast('Check off a purchased item first.');modal('What did the receipt actually say?',`<p>Enter each item’s final cost, including its share of tax or fees. Each item keeps the participants shown below.</p><form data-form="trip"><label class="field">Who paid?<select name="payer">${options()}</select></label><div class="expense-inputs">${items.map(i=>`<div class="receipt-line"><span><strong>${esc(i.name)}</strong><br><span class="small muted">${esc(names(i.members))}</span></span><label class="field">Cost in USD<input type="number" min="0.01" max="100000" step="0.01" required name="cost-${i.id}" aria-label="Cost for ${esc(i.name)}" placeholder="0.00"></label></div>`).join('')}</div><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary">Save purchase costs</button></div></form>`);}
function expenseDialog(){modal('Keep a clear record.',`<form data-form="expense"><label class="field">What was the purchase?<input name="name" required maxlength="80" placeholder="Groceries, game-night snacks, a shared kettle…"></label><div class="form-grid"><label class="field">Total paid (USD)<input type="number" name="amount" min="0.01" max="100000" step="0.01" required placeholder="0.00"></label><label class="field">Who paid?<select name="payer">${options()}</select></label></div>${membersField()}<p class="small muted">The actual total will be split equally among these people. Personal purchases can have one participant.</p><p class="error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary">Record expense</button></div></form>`);}
function repayDialog(id){const amount=balance(state,state.actor).find(([other,c])=>other===id&&c>0)?.[1];if(!amount)return;const pending=state.payments.find(p=>p.from===state.actor&&p.to===id&&!p.confirmed);modal(`Settle with ${esc(person(id).name)}.`,`<div class="balance-big money">${money(amount)}</div><p>For your recorded shared purchases.</p><div class="note warning"><strong>Demo handoff only</strong><p>No payment app or account is connected. In the full product you’d verify the recipient, then complete the transfer in Venmo or your bank’s Zelle service.</p></div>${pending?'<p class="sub">A repayment is already marked as sent. Switch to the recipient in this demo to confirm receipt.</p>':`<form data-form="repay" data-id="${id}" data-cents="${amount}"><label class="field">Payment method<select name="method"><option>Venmo</option><option>Zelle</option><option>Cash</option></select></label><label class="field">Payment note<textarea readonly>${esc(person(state.actor).name)} → ${esc(person(id).name)}: ${money(amount)} for shared household purchases.</textarea></label><p class="small muted">Try the confirmation flow without sending any money.</p><div class="form-actions"><button class="btn primary">Simulate marking as sent</button></div></form>`}`);}
function inspiration(){modal('From your feed to your table.',`<p>Bring a food photo you saved, or try our sample. In a full product, AI would propose a recipe for the household to review.</p><div class="note">This demo uses curated sample suggestions. Photos stay in this browser and are not analyzed or uploaded.</div><div class="photo-input"><div id="photo-preview">${icon('camera')}<p class="small">Choose a food photo</p></div><label class="small">JPG, PNG, or WebP · up to 8 MB<input id="food-photo" type="file" accept="image/jpeg,image/png,image/webp"></label></div><button class="btn full" data-action="sample-photo">Try the sample taco photo</button><div id="photo-result"></div>`);}
function photoResult(){const r=$('#photo-result');r.innerHTML=`<h3>A few ways to make it yours.</h3><p class="small muted">Simulated suggestions for the sample household. These are the same curated recipes regardless of the photo.</p><button class="btn primary full" data-action="recipe" data-id="tacos">Try everyone’s taco night ${icon('arrow')}</button><button class="btn full" data-action="recipe" data-id="salad">Explore a big, bright salad</button>`;}
function editProfile(id){const p=person(id);modal(`${esc(p.name)}’s preferences.`,`<form data-form="profile" data-id="${id}"><label class="field">Food preferences & restrictions<textarea name="note" maxlength="300" required>${esc(p.note)}</textarea></label><div class="form-grid"><label class="field">Convenient store<input name="store" maxlength="50" required value="${esc(p.store)}"></label><label class="field">Why it’s convenient<input name="reason" maxlength="80" required value="${esc(p.reason)}"></label></div><label class="field">Membership note<input name="membership" maxlength="80" value="${esc(p.membership)}" placeholder="None or a self-reported membership"></label><p class="small muted">A note helps coordinate errands. It doesn’t link or share an account.</p><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary">Save preferences</button></div></form>`);}
function autoMatch(){if(!state.voting||!state.matching)return;for(const r of recipes){if(people.every(p=>votesForPlan()[r.id]?.includes(p.id))){const n=addIngredients(state,r,people.map(p=>p.id));if(n)toast(`Everyone matched on ${r.name}. ${n} missing ingredients added.`);}}}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case'close':close();break;case'new-plan':newPlan();break;case'new-themed-plan':newPlan(id);break;case'open-plan':activePlan=id;go('plans');break;case'recipe':recipeDialog(id);break;case'review':reviewDialog(id);break;case'favorite':state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();toast(state.saved.includes(id)?'Recipe saved for later.':'Recipe removed from saved.');break;case'vote':{const votes=votesForPlan()[id]||[];votesForPlan()[id]=votes.includes(state.actor)?votes.filter(x=>x!==state.actor):[...votes,state.actor];autoMatch();save();render();break;}case'theme':state.theme=id;save();render();break;case'add-item':itemDialog();break;case'edit-item':itemDialog(id);break;case'delete-item':state.items=state.items.filter(i=>i.id!==id);save();close();render();toast('Item removed.');break;case'filter':filter=id;render();break;case'claim':case'release':{const i=state.items.find(i=>i.id===id);i.owner=a==='claim'?state.actor:null;save();render();toast(a==='claim'?`${person(state.actor).name} is picking up ${i.name}.`:'Item is up for grabs.');break;}case'assign':assignDialog();break;case'record-trip':recordTrip();break;case'add-expense':expenseDialog();break;case'repay':repayDialog(id);break;case'confirm-payment':{const p=state.payments.find(p=>p.id===id);if(p.to===state.actor){p.confirmed=true;save();render();toast('Receipt confirmed. Balance updated.');}break;}case'inspiration':inspiration();break;case'sample-photo':$('#photo-preview').innerHTML='<img class="preview-photo" src="assets/tacos.jpg" alt="Sample taco inspiration">';photoResult();break;case'edit-profile':editProfile(id);break;case'reset':modal('Start fresh with Maple House?',`<p>This replaces changes made in this browser with the original sample household.</p><div class="form-actions"><button class="btn" data-action="close">Keep my changes</button><button class="btn primary" data-action="confirm-reset">Reset demo</button></div>`);break;case'confirm-reset':state=seed();activePlan='movie';filter='All';query='';save();close();render();toast('Sample household reset.');break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='actor'){state.actor=el.value;save();render();return;}if(el.id==='food-photo'){const file=el.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){toast('Choose a JPG, PNG, or WebP under 8 MB.');el.value='';return;}if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(file);$('#photo-preview').innerHTML=`<img class="preview-photo" src="${photoUrl}" alt="Your selected food inspiration">`;photoResult();return;}switch(el.dataset.change){case'bought':state.items.find(i=>i.id===el.dataset.id).bought=el.checked;break;case'stock':{const p=state.pantry[Number(el.dataset.id)];p.status=el.value;p.confirmed=new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'});break;}case'voting':state.voting=el.checked;if(!state.voting)state.matching=false;break;case'matching':state.matching=el.checked;autoMatch();break;default:return;}save();render();});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const start=e.target.selectionStart;render();$('#search').focus();try{$('#search').setSelectionRange(start,start);}catch{}}});
const cents=value=>{const n=Number(value),c=Math.round(n*100);if(!Number.isFinite(n)||n<=0||c>10000000||Math.abs(n*100-c)>.00001)throw Error('Enter a positive amount with at most two decimal places.');return c;};
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const f=new FormData(form),members=f.getAll('members'),id=form.dataset.id,get=k=>String(f.get(k)||'').trim();try{switch(form.dataset.form){case'new-plan':if(!members.length)throw Error('Choose at least one person joining.');if(!get('name'))throw Error('Give your plan a name.');{const p={id:crypto.randomUUID(),name:get('name'),date:get('date'),time:get('time'),theme:get('theme'),members,menu:null,votes:{tacos:[],salad:[],pasta:[]}};state.plans.push(p);activePlan=p.id;state.theme=p.theme;}break;case'confirm-menu':if(!members.length)throw Error('Choose at least one participant.');{const previousIds=new Set(state.items.map(i=>i.id));const n=addIngredients(state,recipes.find(r=>r.id===id),members);pendingArrival=state.items.filter(i=>!previousIds.has(i.id)).map(i=>i.id);plan().menu=id;plan().members=members;toast(`Menu confirmed. ${n} new ingredients added; existing entries kept.`);}break;case'item':if(!members.length)throw Error('Choose at least one person sharing this item.');if(!get('name')||!get('quantity')||!get('store'))throw Error('Add a name, quantity, and store.');if(state.items.some(i=>i.id!==id&&!i.bought&&normalize(i.name)===normalize(get('name'))))throw Error('This item is already on the list. Close this form and edit its quantity or participants.');{const item={id:id||crypto.randomUUID(),name:get('name'),quantity:get('quantity'),store:get('store'),owner:get('owner')||null,members};if(id)Object.assign(state.items.find(i=>i.id===id),item);else state.items.push({...item,bought:false});}break;case'assign':for(const i of state.items.filter(i=>!i.owner&&!i.bought))i.owner=get(`owner-${i.id}`)||null;toast('Shopping assignments saved.');break;case'trip':{const items=state.items.filter(i=>i.bought&&!i.logged),entries=items.map(i=>({item:i,cost:cents(get(`cost-${i.id}`))}));for(const {item,cost}of entries){state.expenses.push({id:crypto.randomUUID(),name:item.name,payer:get('payer'),cents:cost,members:[...item.members],date:'Just now'});item.logged=true;}toast('Actual costs recorded. Personal and shared items split separately.');}break;case'expense':if(!members.length)throw Error('Choose at least one participant.');if(!get('name'))throw Error('Give the purchase a name.');state.expenses.push({id:crypto.randomUUID(),name:get('name'),payer:get('payer'),cents:cents(get('amount')),members,date:'Just now'});toast('Expense recorded.');break;case'repay':if(state.payments.some(p=>p.from===state.actor&&p.to===id&&!p.confirmed))throw Error('A repayment is already awaiting confirmation.');state.payments.push({id:crypto.randomUUID(),from:state.actor,to:id,cents:Number(form.dataset.cents),method:get('method'),confirmed:false});toast('Demo marked sent. The recipient can confirm receipt.');break;case'profile':Object.assign(person(id),{note:get('note'),store:get('store'),reason:get('reason'),membership:get('membership')||'None'});toast('Preferences saved.');break;}save();close();if(form.dataset.form==='confirm-menu'||form.dataset.form==='item'||form.dataset.form==='assign')go('shopping');else if(form.dataset.form==='trip'||form.dataset.form==='expense'||form.dataset.form==='repay')go('spending');else if(form.dataset.form==='new-plan')go('plans');else render();}catch(err){const error=form.querySelector('.error');if(error)error.textContent=err.message;else toast(err.message);}});
window.addEventListener('hashchange',()=>{if($('#dialog').open)close();render();window.scrollTo({top:0});});
$('#dialog').addEventListener('cancel',()=>{if(photoUrl){URL.revokeObjectURL(photoUrl);photoUrl=null;}});
render();
